 *   IPv4: الشبكة /24. وIPv6: المشترك /64 بحد صارم، والموقع /48.
 * - للبوابة كلها: سقف في الساعة، مع تنبيه المشرف العام عند 70% و90% قبل التوقف.
 */";s:65:"␀PHPStan\Dependency\ExportedNode\ExportedPhpDocNode␀namespaceUses";O:30:"PHPStan\Analyser\NamespaceUses":3:{s:9:"namespace";s:20:"App\Actions\Accounts";s:4:"uses";a:11:{s:8:"rolename";s:18:"App\Enums\RoleName";s:7:"sendsms";s:16:"App\Jobs\SendSms";s:4:"user";s:15:"App\Models\User";s:13:"smscapwarning";s:31:"App\Notifications\SmsCapWarning";s:15:"loginidentifier";s:27:"App\Support\LoginIdentifier";s:13:"networkprefix";s:25:"App\Support\NetworkPrefix";s:5:"cache";s:32:"Illuminate\Support\Facades\Cache";s:3:"log";s:30:"Illuminate\Support\Facades\Log";s:12:"notification";s:39:"Illuminate\Support\Facades\Notification";s:11:"ratelimiter";s:38:"Illuminate\Support\Facades\RateLimiter";s:19:"validationexception";s:41:"Illuminate\Validation\ValidationException";}s:9:"constUses";a:0:{}}}s:59:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀abstract";b:0;s:56:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀final";b:0;s:58:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀extends";N;s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀implements";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀usedTraits";a:0:{}s:70:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀traitUseAdaptations";a:0:{}s:61:"␀PHPStan\Dependency\ExportedNode\ExportedClassNode␀statements";a:7:{i:0;O:58:"PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode":5:{s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀constants";a:1:{i:0;O:57:"PHPStan\Dependency\ExportedNode\ExportedClassConstantNode":3:{s:63:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀name";s:11:"TTL_MINUTES";s:64:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀value";s:2:"10";s:69:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantNode␀attributes";a:0:{}}}s:66:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀public";b:1;s:67:"␀PHPStan\Dependency\ExportedNode\ExportedClassConstantsNode␀private";b:0;s:65:"␀PHPStan\Dependency\ExportedNode\Exported